<?php $base='../';require_once '../config/config.php';require_login();$uid=$_SESSION['user']['user_id'];$st=db()->prepare('SELECT r.*,s.service_name,q.quotation_id,q.amount,q.details,q.status qstatus FROM service_requests r JOIN services s ON s.service_id=r.service_id LEFT JOIN quotations q ON q.request_id=r.request_id WHERE r.customer_id=? ORDER BY r.created_at DESC');$st->execute([$uid]);$rows=$st->fetchAll();$title='My Requests';include '../includes/header.php';?><section class="section"><div class="container"><div class="d-flex justify-content-between"><h1>My Requests</h1><a href="../service_request.php" class="btn btn-gold">New Request</a></div><div class="table-responsive mt-4"><table class="table table-dark"><tr><th>Project</th><th>Service</th><th>Status</th><th>Quotation</th><th>Created</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['project_title'])?></td><td><?=e($r['service_name'])?></td><td><span class="badge badge-gold"><?=e($r['status'])?></span></td><td><?php if($r['quotation_id']):?><?=number_format($r['amount'],2)?> ETB — <?=e($r['qstatus'])?><?php else:?>Not sent<?php endif;?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div></div></section><?php include '../includes/footer.php';?>
